388  bool XCFImageFormat::loadImageProperties(QDataStream &xcf_io, XCFImage &xcf_image)
   389  {
   390      while (true) {
   391          PropType type;
   392          QByteArray bytes;
   393          quint32 rawType;
   394
   395          if (!loadProperty(xcf_io, type, bytes, rawType)) {
   396  //          qDebug() << "XCF: error loading global image properties";
   397              return false;
   398          }
   399
   400          QDataStream property(bytes);
   401
   402          switch (type) {
   403          case PROP_END:
   404              return true;
   405
   406          case PROP_COMPRESSION:
   407              property >> xcf_image.compression;
   408              break;
   409
   410          case PROP_RESOLUTION:
   411              property >> xcf_image.x_resolution >> xcf_image.y_resolution;
   412              break;
   413
   414          case PROP_TATTOO:
   415              property >> xcf_image.tattoo;
   416              break;
   417
   418          case PROP_PARASITES:
   419              while (!property.atEnd()) {
   420                  char *tag;
   421                  quint32 size;
   422
   423                  property.readBytes(tag, size);
   424
   425                  quint32 flags;
   426                  char *data = nullptr;
   427                  property >> flags >> data;
   428
   429                  if (tag && strncmp(tag, "gimp-comment", strlen("gimp-comment")) == 0) {
   430                      xcf_image.image.setText(QStringLiteral("Comment"), QString::fromUtf8(data));
   431                  }
   432
   433                  delete[] tag;
   434                  delete[] data;
   435              }
   436              break;
   437
   438          case PROP_UNIT:
   439              property >> xcf_image.unit;
   440              break;
   441
   442          case PROP_PATHS:    // This property is ignored.
   443              break;
   444
   445          case PROP_USER_UNIT:    // This property is ignored.
   446              break;
   447
   448          case PROP_COLORMAP:
   449              property >> xcf_image.num_colors;
   450              if (xcf_image.num_colors < 0 || xcf_image.num_colors > 65535) {
   451                  return false;
   452              }
   453
   454              xcf_image.palette.reserve(xcf_image.num_colors);
   455
   456              for (int i = 0; i < xcf_image.num_colors; i++) {
   457                  uchar r, g, b;
   458                  property >> r >> g >> b;
   459                  xcf_image.palette.push_back(qRgb(r, g, b));
   460              }
   461              break;
   462
   463          default:
   464  //                  qDebug() << "XCF: unimplemented image property" << rawType
   465  //                          << ", size " << bytes.size() << endl;
   466              break;
   467          }
   468      }
